int csi_rf1_predict(const float *input, double *proba) {
    if (!input || !proba) return -1;

    float x[5];
    for (int i = 0; i < 5; ++i) {
        x[i] = isnan(input[i]) ? g_imputer_medians[i] : input[i];
    }

    double sum_p1 = 0.0;
    for (int t = 0; t < 300; ++t) {
        int idx = g_roots[t];
        while (g_nodes[idx].feature >= 0) {
            if (x[g_nodes[idx].feature] <= g_nodes[idx].threshold) {
                idx = g_nodes[idx].left;
            } else {
                idx = g_nodes[idx].right;
            }
        }
        sum_p1 += g_nodes[idx].proba;
    }

    double p1 = sum_p1 / 300.0;
    proba[1] = p1;
    proba[0] = 1.0 - p1;
    return (p1 >= CSI_RF1_DEFAULT_THRESHOLD) ? 1 : 0;
}
